//! `shapes` as Rust: its answers as typed values, its questions and policy
//! from `examples/jud/shapes.jud`, a rubric asked about an image: whether it
//! holds a filled circle (a Noul) and where (a Box).
//!
//! Generated by the jud plugin's `/jud:rust` from `examples/jud/shapes.jud`,
//! questions `sha256:ce690f12891229b8596a87345f78d4763fefa03a527b1e9d4aa3ca6dc5876081`.
//! The file is compiled in (`include_str!`) and parsed at run time:
//!
//! - a change to the policy (a bar, a band, `jud tune`) takes a rebuild,
//!   which cargo does on its own, and no regeneration;
//! - a change to a question takes a regeneration, and the test at the bottom
//!   fails until it is done.
//!
//! The rubric asks about an image, so [`decide`] takes the request's
//! [`Assets`] beside the state: the image under the reference the state
//! carries (`{"image": "shape-01"}`, with `shape-01` in the assets), checked
//! against the API's limits when it is read. A Box always answers with a
//! box, found or not: `circle_present` says whether there is one, `circle`
//! where, and the policy's confidence bar on the Box defers a box the model
//! is unsure of. The box is in fractions of the image; the caller, who has
//! the image, turns it into pixels.
//!
//! ```ignore
//! mod shapes;
//! use shapes::Located;
//!
//! #[tokio::main(flavor = "current_thread")]
//! async fn main() -> Result<(), Box<dyn std::error::Error>> {
//!     let backend = judgment::Client::from_env()?; // or judgment::Fake, judgment::Replay
//!     let image = judgment::Image::read("frames/shape-01.png")?;
//!     let (width, height) = (image.width(), image.height());
//!     let mut assets = judgment::Assets::new();
//!     assets.insert("shape-01", image)?;
//!     let state = serde_json::json!({ "image": "shape-01" });
//!     // A Box needs Jev 1.14: `jev-preview` until `jev-latest` moves.
//!     let decision = shapes::decide(&backend, "jev-preview", &state, &assets).await?;
//!     if decision.circle_present.yes {
//!         match decision.circle {
//!             Located::Act { edges, .. } => {
//!                 let crop = edges.padded(0.02).to_pixels(width, height);
//!                 println!("crop x {}..{}, y {}..{}", crop.left, crop.right, crop.top, crop.bottom);
//!             }
//!             Located::Defer { confidence, bar, .. } => {
//!                 println!("a circle, but the box is unsure: {confidence:.2} under {bar:.2}");
//!             }
//!         }
//!     }
//!     Ok(())
//! }
//! ```

// A generated API: a program uses the parts it needs and no warning should
// ask it to delete the rest.
#![allow(dead_code)]

use std::sync::OnceLock;

use judgment::jud::{Rubric, Supplied, Verdict};
use judgment::{Assets, BoxEdges, Confidence, Questions, Response, SystemOne};

/// The rubric's text, compiled in from the file and parsed at run time.
/// The request is lowered from it, so it is byte for byte what `jud lower`
/// sends for the same file, and recordings made with `jud record` replay
/// against it, keyed by the state and the image alike.
pub const SOURCE: &str = include_str!("shapes.jud");

/// The rubric's path from the crate root, as errors and the test name it.
pub const RUBRIC: &str = "examples/jud/shapes.jud";

/// The questions fingerprint this module was generated from (`jud check`).
pub const QUESTIONS_FINGERPRINT: &str =
    "sha256:ce690f12891229b8596a87345f78d4763fefa03a527b1e9d4aa3ca6dc5876081";

/// The parsed rubric, read once.
///
/// # Errors
///
/// [`Error::Rubric`] when [`SOURCE`] is not a valid rubric, which the test
/// below rules out.
pub fn rubric() -> Result<&'static Rubric, Error> {
    static PARSED: OnceLock<Rubric> = OnceLock::new();
    if let Some(rubric) = PARSED.get() {
        return Ok(rubric);
    }
    let parsed = Rubric::parse(SOURCE)?;
    Ok(PARSED.get_or_init(|| parsed))
}

/// A Noul's verdict: the gate's yes or no, and the probability of yes it
/// was read from.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct YesNo {
    /// The gate's answer: the probability met its threshold (exceeded it,
    /// when the gate is `strict`).
    pub yes: bool,
    /// The model's probability of yes.
    pub probability: f64,
}

/// A Box's verdict: where the thing is, as fractions of the image from its
/// top-left corner, when the gate let the box through; else the box the
/// model gave and the bar it fell under. A crop is
/// `edges.padded(..).to_pixels(width, height)` with the image's size, which
/// the caller has and the rubric does not.
#[derive(Debug, Clone, PartialEq)]
pub enum Located {
    /// The box met the gate's bar, or the question has no gate: act on
    /// `edges`.
    Act {
        /// The box, as the model gave it.
        edges: BoxEdges,
        /// The model's confidence in it, when it gave one.
        confidence: Option<f64>,
        /// The band it reached, when the gate has `bands`.
        band: Option<String>,
    },
    /// The box was below the gate's last bar: do not act on it alone.
    Defer {
        /// The box the model would have given.
        nearest: BoxEdges,
        /// The model's confidence, 0 when it gave none.
        confidence: f64,
        /// The bar it was below.
        bar: f64,
    },
}

impl Located {
    /// The box to act on, when the gate let it through.
    #[must_use]
    pub fn edges(&self) -> Option<BoxEdges> {
        match self {
            Self::Act { edges, .. } => Some(*edges),
            Self::Defer { .. } => None,
        }
    }
}

/// Every question's verdict, typed. The bars that decide them are the
/// rubric's policy, read from the file.
#[derive(Debug, Clone, PartialEq)]
pub struct Decision {
    /// Is there a filled circle in `image`?
    pub circle_present: YesNo,
    /// The filled circle in `image`.
    pub circle: Located,
}

/// The request for `state`, as the rubric lowers it.
///
/// # Errors
///
/// [`Error::Rubric`] when the state cannot be lowered.
pub fn questions(state: &serde_json::Value) -> Result<Questions, Error> {
    Ok(rubric()?.lower(state, &Supplied::default())?)
}

/// Read `response`, the answer to `asked`, through the rubric's policy.
///
/// # Errors
///
/// [`Error::Rubric`] when the response does not answer `asked`;
/// [`Error::Missing`] when the rubric no longer asks a question this module
/// reads, and [`Error::Unexpected`] when a verdict holds something this
/// module does not know: both mean it is older than the rubric.
pub fn read(asked: &Questions, response: &Response) -> Result<Decision, Error> {
    let verdicts = rubric()?.apply(asked, response)?;
    let verdict = |id: &'static str| verdicts.get(id).ok_or(Error::Missing(id));
    Ok(Decision {
        circle_present: yes_no("circle_present", verdict("circle_present")?)?,
        circle: located("circle", verdict("circle")?)?,
    })
}

/// Ask `backend` about `state` and the images in `assets` with `model`, and
/// read the answer. Every reference the state carries must be in `assets`,
/// and every image in `assets` referenced, as the API requires; the backend
/// refuses the request otherwise, before anything is sent.
///
/// # Errors
///
/// [`Error::State`] when `state` does not serialise to JSON,
/// [`Error::Backend`] when the call fails, and what [`read`] returns.
pub async fn decide<B: SystemOne>(
    backend: &B,
    model: &str,
    state: &impl serde::Serialize,
    assets: &Assets,
) -> Result<Decision, Error> {
    let state = serde_json::to_value(state).map_err(Error::State)?;
    let asked = questions(&state)?;
    let response = backend
        .answer_with_assets(&state, model, &asked, assets)
        .await?;
    read(&asked, &response)
}

fn yes_no(id: &'static str, verdict: &Verdict) -> Result<YesNo, Error> {
    match verdict {
        Verdict::Yes { probability } => Ok(YesNo {
            yes: true,
            probability: probability.value(),
        }),
        Verdict::No { probability } => Ok(YesNo {
            yes: false,
            probability: probability.value(),
        }),
        other => Err(Error::unexpected(id, &format!("{other:?}"))),
    }
}

/// A Box's verdict is `located` with its edges, or deferred with the edges
/// as the text `top,bottom,left,right`, which reads back into edges.
fn located(id: &'static str, verdict: &Verdict) -> Result<Located, Error> {
    match verdict {
        Verdict::Located {
            edges,
            confidence,
            band,
            ..
        } => Ok(Located::Act {
            edges: *edges,
            confidence: confidence.map(Confidence::value),
            band: band.clone(),
        }),
        Verdict::Deferred(deferred) => Ok(Located::Defer {
            nearest: edges_from_text(id, &deferred.nearest)?,
            confidence: deferred.confidence.value(),
            bar: deferred.bar,
        }),
        other => Err(Error::unexpected(id, &format!("{other:?}"))),
    }
}

fn edges_from_text(id: &'static str, text: &str) -> Result<BoxEdges, Error> {
    let mut parts = text.split(',').map(str::parse::<f64>);
    match (
        parts.next(),
        parts.next(),
        parts.next(),
        parts.next(),
        parts.next(),
    ) {
        (Some(Ok(top)), Some(Ok(bottom)), Some(Ok(left)), Some(Ok(right)), None) => {
            Ok(BoxEdges::new(top, bottom, left, right))
        }
        _ => Err(Error::unexpected(id, text)),
    }
}

/// What can go wrong between the rubric, the backend and this module.
#[derive(Debug)]
pub enum Error {
    /// The rubric did not parse, lower or read the response.
    Rubric(judgment::jud::Error),
    /// The state did not serialise to JSON.
    State(serde_json::Error),
    /// The backend call failed, an image the request lacks or the API
    /// refuses included.
    Backend(judgment::Error),
    /// A question this module reads has no verdict: the rubric no longer
    /// asks it, so this module is older than the rubric.
    Missing(&'static str),
    /// A verdict this module cannot type: it is older than the rubric.
    Unexpected {
        /// The question.
        question: &'static str,
        /// What the verdict held.
        found: String,
    },
}

impl Error {
    fn unexpected(question: &'static str, found: &str) -> Self {
        Self::Unexpected {
            question,
            found: found.to_owned(),
        }
    }
}

impl std::fmt::Display for Error {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Rubric(e) => write!(f, "{RUBRIC}: {e}"),
            Self::State(e) => write!(f, "state: {e}"),
            Self::Backend(e) => write!(f, "backend: {e}"),
            Self::Missing(id) => write!(
                f,
                "no verdict for `{id}`; regenerate this module from {RUBRIC}"
            ),
            Self::Unexpected { question, found } => write!(
                f,
                "`{question}`: unexpected {found}; regenerate this module from {RUBRIC}"
            ),
        }
    }
}

impl std::error::Error for Error {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::Rubric(e) => Some(e),
            Self::State(e) => Some(e),
            Self::Backend(e) => Some(e),
            Self::Missing(_) | Self::Unexpected { .. } => None,
        }
    }
}

impl From<judgment::jud::Error> for Error {
    fn from(e: judgment::jud::Error) -> Self {
        Self::Rubric(e)
    }
}

impl From<judgment::Error> for Error {
    fn from(e: judgment::Error) -> Self {
        Self::Backend(e)
    }
}

#[cfg(test)]
mod tests {
    use judgment::Question;

    use super::*;

    /// Fails when the rubric's questions changed since this module was
    /// generated: regenerate it.
    #[test]
    fn the_module_matches_the_rubric() -> Result<(), Error> {
        let rubric = rubric()?;
        assert_eq!(
            rubric.fingerprint(),
            QUESTIONS_FINGERPRINT,
            "{RUBRIC}'s questions changed: regenerate this module"
        );
        let present = rubric.questions.get("circle_present").map(|q| &q.question);
        assert!(
            matches!(present, Some(Question::Noul { .. })),
            "circle_present is not a Noul"
        );
        let circle = rubric.questions.get("circle").map(|q| &q.question);
        assert!(
            matches!(circle, Some(Question::Box { .. })),
            "circle is not a Box"
        );
        Ok(())
    }

    /// A deferred Box carries its edges as text, which read back as edges;
    /// anything else is this module's error, never a panic.
    #[test]
    fn a_deferred_box_reads_its_edges_back() -> Result<(), Error> {
        assert_eq!(
            edges_from_text("circle", "0.1,0.6,0.2,0.7")?,
            BoxEdges::new(0.1, 0.6, 0.2, 0.7)
        );
        assert!(edges_from_text("circle", "0.1,0.6").is_err());
        assert!(edges_from_text("circle", "a,b,c,d").is_err());
        Ok(())
    }
}
